"""Write the Kaggle Benchmarks task file that generates one passage per (prompt, model).

The prompt bank and the length percentiles are embedded in the task file, so the task needs no dataset.
Usage: make_task.py <prompt bank csv> <first row> <last row> <out .py>
"""
import json
import sys
from pathlib import Path

import pandas as pd

HERE = Path(__file__).parent
TEMPLATE = r'''
# Generated by make_task.py. One passage per prompt for the model this task runs against.
import concurrent.futures as cf
import hashlib
import json
import os
import time

import kaggle_benchmarks as kbench
from openai import OpenAI

PROMPTS = __PROMPTS__
PCTL = __PCTL__
LABELS = __LABELS__
SUFFIX = " Write it as a single self-contained paragraph of about {n} words, with no title, headings or lists."


def target_words(prompt_id, model):
    # Seeded per (prompt, model), drawn from the pooled train word-count distribution, clipped to 40..250.
    h = int(hashlib.sha256(f"{prompt_id}|{model}".encode()).hexdigest()[:8], 16) / 0xFFFFFFFF
    i = h * 100
    lo = int(i)
    v = PCTL[lo] + (PCTL[min(lo + 1, 100)] - PCTL[lo]) * (i - lo)
    return int(min(250, max(40, round(v / 5) * 5)))


def call(client, model, p):
    n = target_words(p["prompt_id"], model)
    text = p["prompt_body"] + SUFFIX.format(n=n)
    t = time.time()
    try:
        r = client.chat.completions.create(model=model, max_tokens=__MAXTOK__, messages=[{"role": "user", "content": text}])
        d = r.model_dump()
        return dict(prompt_id=p["prompt_id"], model_requested=model, target_words=n, request=text, ok=True,
                    seconds=round(time.time() - t, 2), response=d)
    except Exception as e:
        return dict(prompt_id=p["prompt_id"], model_requested=model, target_words=n, request=text, ok=False,
                    seconds=round(time.time() - t, 2), error=repr(e)[:2000])


@kbench.task(name="__NAME__")
def generate(llm) -> float:
    model = llm.model
    base = os.environ["MODEL_PROXY_URL"].rstrip("/")
    for suffix in ("/openapi", "/genai"):
        if base.endswith(suffix):
            base = base[: -len(suffix)]
    print("proxy path", base.split("//")[-1].split("/", 1)[-1], "model", model)
    client = OpenAI(base_url=base + "/openapi", api_key=os.environ["MODEL_PROXY_API_KEY"])
    rows = PROMPTS if any(model.split("/")[-1].startswith(l) for l in LABELS) else PROMPTS[:1]
    out = []
    with cf.ThreadPoolExecutor(4) as ex:
        for res in ex.map(lambda p: call(client, model, p), rows):
            out.append(res)
    slug = model.replace("/", "__").replace("@", "_")
    with open(f"/kaggle/working/gen__{slug}.jsonl", "w") as f:
        for r in out:
            f.write(json.dumps(r, default=str) + "\n")
    ok = sum(r["ok"] for r in out)
    print(model, ok, "of", len(out), "ok")
    return ok / max(1, len(out))


generate.run(kbench.llm)
'''

LABELS = ["claude-opus-4-6", "claude-opus-4-8", "claude-opus-5", "claude-sonnet-5", "gemini-3.1-pro-preview",
          "gemini-3.6-flash", "gemini-3.8-flash", "gpt-5.5", "gpt-5.6-luna", "gpt-5.6-sol", "gpt-5.6-terra", "gpt-6-astra"]


def main(bank, a, b, out, name, maxtok=6000):
    df = pd.read_csv(bank).iloc[int(a):int(b)]
    prompts = df[["prompt_id", "prompt_body"]].to_dict("records")
    s = (TEMPLATE.replace("__PROMPTS__", json.dumps(prompts, ensure_ascii=False))
         .replace("__PCTL__", json.dumps(json.load(open(HERE / "train_word_percentiles.json"))))
         .replace("__LABELS__", json.dumps(LABELS)).replace("__NAME__", name).replace("__MAXTOK__", str(maxtok)))
    Path(out).write_text(s)
    print(len(prompts), "prompts written to", out)


if __name__ == "__main__":
    main(*sys.argv[1:])
